    text=f'已执行{c.intent}（{c.primary_method}）；有效观测{len(rows)}条。计算结果：'+json.dumps(out,ensure_ascii=False,allow_nan=False)+'。'
    public_text=f'已完成{c.intent}，使用{len(rows)}条有效数据。'
